import{_ as a,o as r,c as i,a2 as t}from"./chunks/framework.0o43zZ6z.js";const f=JSON.parse('{"title":"手機安裝 App","description":"米勒麻醉學 PWA 的 iPhone、iPad 與 Android 安裝步驟，以及離線閱讀測試。","frontmatter":{"title":"手機安裝 App","description":"米勒麻醉學 PWA 的 iPhone、iPad 與 Android 安裝步驟，以及離線閱讀測試。","outline":[2,3]},"headers":[],"relativePath":"install.md","filePath":"install.md"}'),n={name:"install.md"};function e(l,o,s,p,h,d){return r(),i("div",null,[...o[0]||(o[0]=[t('<h1 id="手機安裝-app" tabindex="-1">手機安裝 App <a class="header-anchor" href="#手機安裝-app" aria-label="Permalink to &quot;手機安裝 App&quot;">​</a></h1><p>將米勒麻醉學以 <strong>PWA 網頁 App</strong> 加入主畫面，即可用獨立視窗開啟，閱讀 87 章與搜尋中英關鍵字。</p><p><a href="/Miller-s_anesthesia_10ed/chapters/">閱讀章節</a> · <a href="#iphone">iPhone／iPad 安裝步驟</a> · <a href="#android">Android 安裝步驟</a></p><h2 id="安裝前準備" tabindex="-1">安裝前準備 <a class="header-anchor" href="#安裝前準備" aria-label="Permalink to &quot;安裝前準備&quot;">​</a></h2><ol><li>使用手機開啟本網站的 <strong>HTTPS 網址</strong>。若從 LINE、Facebook 或其他 App 開啟，請改用 Safari 或 Chrome。</li><li>連接 Wi-Fi，並預留至少約 <strong>500 MiB</strong> 的儲存空間，供全文、圖表與原頁影像離線使用。</li><li>等待畫面左下角由「正在準備離線內容…」變成 <strong>「已可離線閱讀」</strong>。第一次下載需要時間，請保持頁面開啟。</li></ol><h2 id="iphone" tabindex="-1">iPhone／iPad：使用 Safari <a class="header-anchor" href="#iphone" aria-label="Permalink to &quot;iPhone／iPad：使用 Safari {#iphone}&quot;">​</a></h2><ol><li>在 <strong>Safari</strong> 開啟本網站。</li><li>點選 <strong>分享</strong> 按鈕（方框向上箭頭）；部分版本需先開啟「⋯」選單。</li><li>向下捲動，選擇 <strong>加入主畫面</strong>。若沒有此項目，可查看分享選單的「編輯動作」。</li><li>名稱使用 <strong>米勒麻醉學</strong>。若有「以網頁 App 開啟」選項，請開啟。</li><li>點選 <strong>加入</strong>，回到主畫面開啟「米勒麻醉學」圖示。</li><li>在 App 內保持連線，確認也顯示「已可離線閱讀」。</li></ol><p>Safari 與主畫面 App 的儲存狀態可能不同，請在安裝後開啟的 App 內完成一次離線確認。</p><h2 id="android" tabindex="-1">Android：使用 Chrome <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android：使用 Chrome {#android}&quot;">​</a></h2><ol><li>在 <strong>Chrome</strong> 開啟本網站。</li><li>若左下角出現 <strong>安裝手冊</strong>，點選並依提示安裝。</li><li>也可點選 Chrome 右上角 <strong>⋮</strong> → <strong>安裝應用程式</strong> 或 <strong>加到主畫面</strong>。不同版本的選單名稱可能不同。</li><li>確認名稱 <strong>米勒麻醉學</strong>，按下 <strong>安裝／加入</strong>。</li><li>從主畫面開啟 App，確認畫面左下角顯示 <strong>已可離線閱讀</strong>。</li></ol><p>若選單暫時沒有安裝項目，請確認網址使用 HTTPS、不是無痕模式，並更新 Chrome 後重新整理。</p><h2 id="offline" tabindex="-1">確認可離線閱讀 <a class="header-anchor" href="#offline" aria-label="Permalink to &quot;確認可離線閱讀 {#offline}&quot;">​</a></h2><ol><li>開啟安裝好的 App，等待「已可離線閱讀」。</li><li>開啟飛航模式，並確認 Wi-Fi 也已關閉。</li><li>開啟尚未讀過的章節，例如 <strong>第 87 章：醫學文獻判讀</strong>，再重新整理。</li><li>搜尋 <strong>氣道管理</strong> 或 <strong>propofol</strong>，確認有結果。</li><li>開啟含圖片的章節，確認圖表及「原始表格與符號」中的原頁影像可以顯示。</li></ol><p>若顯示「尚未完成離線快取」，請恢復網路並等待完成。瀏覽器清除網站資料、裝置空間不足或重新安裝後，需要重新下載。</p><h2 id="更新與重新安裝" tabindex="-1">更新與重新安裝 <a class="header-anchor" href="#更新與重新安裝" aria-label="Permalink to &quot;更新與重新安裝&quot;">​</a></h2><p>網站更新後會顯示 <strong>手冊有新版本</strong>。請在有網路時按 <strong>立即更新</strong>，並再次確認離線狀態。</p><p>若已安裝舊網站的圖示，請先安裝並確認這個新網站可正常開啟，再刪除舊圖示。新舊網址的離線資料各自儲存，無法共用。</p><p><a href="/Miller-s_anesthesia_10ed/chapters/">回到章節目錄</a> · <a href="/Miller-s_anesthesia_10ed/guide.html">完整使用說明</a></p>',18)])])}const c=a(n,[["render",e]]);export{f as __pageData,c as default};
